from core.rules import RuleMachine


class SafeSortedDestinationRule:
    """Permite movimientos hacia pilas no vacías que siguen ordenadas; opcionalmente abre
    la puerta a vacíos cuando la fuente está desordenada para desatascar bloqueos."""

    name = "safe_sorted_destination_rule"

    def __init__(
        self,
        allow_empty_destination: bool = True,
        prefer_empty_when_source_unsorted: bool = True,
        prioritize_tighter_sorted_destinations: bool = True,
    ):
        self.allow_empty_destination = allow_empty_destination
        self.prefer_empty_when_source_unsorted = prefer_empty_when_source_unsorted
        self.prioritize_tighter_sorted_destinations = prioritize_tighter_sorted_destinations

    def _is_sorted_after_push(self, partial, so, sd):
        if partial.h(so) <= 0 or partial.h(sd) >= partial.H:
            return False
        src_group = partial.g(so)
        if src_group < 0:
            return False

        if so == sd:
            return False

        if partial.h(sd) == 0:
            return self.allow_empty_destination and (
                not self.prefer_empty_when_source_unsorted or not partial.is_sorted_stack(so)
            )

        if not partial.is_sorted_stack(sd):
            return False

        # Stack order is non-increasing bottom -> top, so the moved container must not
        # be larger than the current top of the destination.
        return partial.g(sd) >= src_group

    def _priority_key(self, partial, action):
        so = action.so
        sd = action.sd
        src_group = partial.g(so)
        dest_h = partial.h(sd)

        if dest_h == 0:
            # Empty destination: useful mainly as a release move from a bad stack.
            return (
                1 if partial.is_sorted_stack(so) else 0,
                src_group,
                sd,
                so,
            )

        dest_top = partial.g(sd)
        slack = partial.e(sd)

        # Prefer safe sorted destinations; optionally favor tighter fits.
        if self.prioritize_tighter_sorted_destinations:
            return (
                2,
                dest_top - src_group,
                slack,
                dest_top,
                sd,
                so,
            )
        return (
            2,
            dest_top,
            slack,
            sd,
            so,
        )

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            if self._is_sorted_after_push(partial, a.so, a.sd):
                allowed.append(a)

        allowed.sort(key=lambda a: self._priority_key(partial, a))
        return allowed

    def score(self, partial, memory, action):
        # Compatible with skeletons that consult scores after allowed().
        return self._priority_key(partial, action)


def build_component(problem, **params):
    return RuleMachine(
        problem,
        [
            SafeSortedDestinationRule(
                allow_empty_destination=params.get("allow_empty_destination", True),
                prefer_empty_when_source_unsorted=params.get("prefer_empty_when_source_unsorted", True),
                prioritize_tighter_sorted_destinations=params.get(
                    "prioritize_tighter_sorted_destinations", True
                ),
            )
        ],
    )
